using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions; namespace JTradeERP.Application.Features.MasterData.Categories.DeleteCategory; public sealed class DeleteCategoryHandler(IApplicationDbContext db) : IRequestHandler<DeleteCategoryCommand> { public async Task Handle(DeleteCategoryCommand r,CancellationToken ct){var e=db.Categories.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Category not found.");if(db.Products.Any(x=>x.CategoryId==r.Id))throw new ConflictException("Category is referenced by a Product.");db.Remove(e);await db.SaveChangesAsync(ct);} }
